</style></head><body><nav><div class="brand"><b>N</b> Nodexa</div><a class="btn" href="/">Kontrolpanel</a></nav><section class="hero"><h1>Game servers. Uden besvær.</h1><div class="sub">Vælg din server, ressourcerne er klar til Nodexa Control Panel.</div></section><main class="wrap"><div class="grid">@forelse($products as $p)<article class="card {{$p->featured?'featured':''}}"><div class="tag">{{$p->game}} {{$p->featured?'• POPULÆR':''}}</div><h2>{{$p->name}}</h2><p style="color:#93a8c4">{{$p->description}}</p><div class="price">{{number_format($p->price_monthly,2,',','.')}} kr <small>/ måned</small></div><div class="specs">{{$p->memory}} MB RAM<br>{{$p->disk}} MB lager<br>{{$p->cpu}}% CPU<br>{{$p->databases}} databaser · {{$p->backups}} backups</div><p><a class="btn" href="{{route('store.product',$p)}}">Konfigurér & bestil</a></p></article>@empty<div class="card"><h2>Produkter kommer snart</h2><p class="sub">Der er endnu ingen aktive serverpakker.</p></div>@endforelse</div></main></body></html>
